const items = $input.all();
const now = new Date();
const results = [];

for (const item of items) {
  const finishedAt = new Date(item.json.finished_at);
  const daysSinceDelivery = Math.floor((now - finishedAt) / (1000 * 60 * 60 * 24));

  const lastContact = item.json.last_pos_venda_contact ? new Date(item.json.last_pos_venda_contact) : null;
  const daysSinceLastContact = lastContact ? Math.floor((now - lastContact) / (1000 * 60 * 60 * 24)) : 999;

  let shouldContact = false;
  let templateType = '';
  let priority = 0;

  // 7 dias - mantém > 5
  if (daysSinceDelivery >= 6 && daysSinceDelivery <= 8 && daysSinceLastContact > 5) {
    shouldContact = true;
    templateType = 'feedback_inicial';
    priority = 3;
  }
  // 30 dias - MUDOU para >= 15
  else if (daysSinceDelivery >= 28 && daysSinceDelivery <= 32 && daysSinceLastContact >= 15) {
    shouldContact = true;
    templateType = 'satisfacao_30_dias';
    priority = 4;
  }
  // 60 dias - MUDOU para >= 20
  else if (daysSinceDelivery >= 58 && daysSinceDelivery <= 62 && daysSinceLastContact >= 20) {
    shouldContact = true;
    templateType = 'oferta_complementar_60';
    priority = 3;
  }
  // 90 dias - MUDOU para >= 30
  else if (daysSinceDelivery >= 88 && daysSinceDelivery <= 92 && daysSinceLastContact >= 30) {
    shouldContact = true;
    templateType = 'pos_venda_principal_90';
    priority = 5;
  }
  // 120 dias - MUDOU para >= 30
  else if (daysSinceDelivery >= 118 && daysSinceDelivery <= 122 && daysSinceLastContact >= 30) {
    shouldContact = true;
    templateType = 'servicos_adicionais_120';
    priority = 4;
  }
  // 180 dias - MUDOU para >= 60
  else if (daysSinceDelivery >= 178 && daysSinceDelivery <= 210 && daysSinceLastContact >= 60) {
    shouldContact = true;
    templateType = 'manutencao_180';
    priority = 3;
  }
  // 270 dias - MUDOU para >= 90
  else if (daysSinceDelivery >= 268 && daysSinceDelivery <= 300 && daysSinceLastContact >= 90) {
    shouldContact = true;
    templateType = 'renovacao_270';
    priority = 2;
  }
  // 365 dias - MUDOU para >= 120
  else if (daysSinceDelivery >= 363 && daysSinceDelivery <= 395 && daysSinceLastContact >= 120) {
    shouldContact = true;
    templateType = 'aniversario_1_ano';
    priority = 4;
  }

  if (shouldContact) {
    results.push({
      json: {
        ...item.json,
        days_since_delivery: daysSinceDelivery,
        days_since_last_contact: daysSinceLastContact,
        template_type: templateType,
        priority: priority,
        should_contact: shouldContact
      }
    });
  }
}

results.sort((a, b) => b.json.priority - a.json.priority);

return results;

