// Anti-duplicação: Não registra se já registrou nos últimos 2 minutos
const phone = $('Prepara Contexto Resposta').item.json.dados_contexto.session.phone_number;
const tipo = $('Agente Resposta [AI_AGENT_NAME]').item.json.output.tipo_manifestacao;
const now = Date.now();

// Chave de cache simples (na memória do node)
if (!global.lastRegistrations) {
  global.lastRegistrations = {};
}

const cacheKey = `${phone}-${tipo}`;
const lastTime = global.lastRegistrations[cacheKey] || 0;

if (now - lastTime < 120000) { // 2 minutos
  return []; // Não registra (evita duplicação)
}

// Atualiza cache
global.lastRegistrations[cacheKey] = now;

// Formata os dados para registro
const briefing = $('Agente Resposta [AI_AGENT_NAME]').item.json.output.briefing;
let produtoServico = 'Não especificado';

if (briefing && briefing.tipo_interesse) {
  produtoServico = briefing.tipo_interesse.descricao;
}

return [{
  json: {
    nome_cliente: $('Prepara Contexto Resposta').item.json.dados_contexto.nome_cliente,
    telefone: phone,
    produto_original: $('Prepara Contexto Resposta').item.json.dados_contexto.produto_vendido,
    dias_desde_entrega: Math.round((Date.now() - new Date($('Prepara Contexto Resposta').item.json.dados_contexto.session.finished_at).getTime()) / (1000 * 60 * 60 * 24)),
    template_usado: $('Prepara Contexto Resposta').item.json.dados_contexto.session.last_template_type || 'resposta_cliente',
    lead_qualificado: $('Agente Resposta [AI_AGENT_NAME]').item.json.output.lead_qualificado ? 'Sim' : 'Não',
    tipo_manifestacao: tipo,
    encaminhado_para: $('Agente Resposta [AI_AGENT_NAME]').item.json.output.encaminhar_para || 'N/A',
    data_contato: new Date().toLocaleString('pt-BR', {timeZone: 'America/Sao_Paulo'}),
    acao_tomada: $('Agente Resposta [AI_AGENT_NAME]').item.json.output.acao_tomada,
    produto_servico_oferecido: produtoServico
  }
}];

// Extrai dados relevantes das vendas e prepara para verificação
const vendas = $input.first().json;
const results = [];

if (!vendas || !Array.isArray(vendas)) {
  return [];
}

for (const venda of vendas) {
  // Valida se tem telefone
  const telefone = venda.customer?.phone_number || venda.customer?.mobile_phone;

  if (!telefone) {
    continue; // Pula se não tiver telefone
  }

  // Normaliza telefone (remove espaços, parênteses, hífens)
  const telefoneNormalizado = telefone.replace(/[^0-9+]/g, '');

  // Garante que começa com +55
  const telefoneFinal = telefoneNormalizado.startsWith('+') ? telefoneNormalizado : '+55' + telefoneNormalizado;

  // Extrai produto vendido (simplificado - ajustar conforme estrutura real do ERP)
  const produtoDescricao = venda.items && venda.items[0] ? venda.items[0].description : 'Produto não especificado';

  results.push({
    json: {
      erp_sale_id: venda.id,
      customer_name: venda.customer?.name || 'Cliente',
      phone_number: telefoneFinal,
      produto_vendido: produtoDescricao,
      data_venda: venda.emission || venda.created_at,
      valor_total: venda.total || 0,
      status_erp: venda.status
    }
  });
}

return results;

